/**
 * Jinx Al-Hadikhia + Mastermind: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Al-Hadikhia
 * Wiki: https://wiki.bloodontheclocktower.com/Mastermind
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';

describe('Al-Hadikhia + Mastermind jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alhadikhia', 'mastermind');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alhadikhia')?.name).toBe('Al-Hadikhia');
		expect(data.byId.get('mastermind')?.name).toBe('Mastermind');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alhadikhia', 'mastermind'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alhadikhia'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['mastermind'])).not.toContain(jinx);
	});

	it.todo('enforces the rule the jinx imposes');
});
